template.script:
    document.addEventListener('DOMContentLoaded', function () {
        const rewardsPage = document.querySelector('.intern-rewards-page');
        const dynamicVoucherTitle = document.getElementById('dynamicVoucherTitle');
        const badgeUnlockModalElement = document.getElementById('badgeUnlockModal');
        const badgeUnlockModalTitle = document.getElementById('badgeUnlockModalTitle');
        const badgeUnlockModalDescription = document.getElementById('badgeUnlockModalDescription');
        const badgeUnlockModalIcon = document.getElementById('badgeUnlockModalIcon');
        const confettiColors = ['#FFD285', '#bf9e3c', '#0e4174', '#709ECB', '#FFF2D1'];
        const rewardSound = new Audio('/famtech_intern_dashboard/static/src/website/audio/Success_Sound-Effect.mp3');

        rewardSound.preload = 'auto';

        function playRewardSound() {
            rewardSound.currentTime = 0;
            rewardSound.play().catch(function () {
                // Ignore blocked autoplay errors; modal visuals still continue.
            });
        }

        function launchRewardConfetti(modalElement) {
            const confettiLayer = modalElement.querySelector('.reward-confetti-layer');
            if (!confettiLayer) return;
            confettiLayer.innerHTML = '';

            function createBurst() {
                for (let i = 0; i < 40; i++) {
                    const piece = document.createElement('span');
                    const color = confettiColors[i % confettiColors.length];
                    const left = Math.random() * 100;
                    const delay = Math.random() * 0.3;
                    const drift = (Math.random() * 300) - 150;
                    const rotate = (Math.random() * 720) - 360;
                    const size = Math.random() * 8 + 6;

                    piece.className = 'reward-confetti-piece';
                    piece.style.left = left + '%';
                    piece.style.backgroundColor = color;
                    piece.style.animationDelay = delay + 's';
                    piece.style.setProperty('--confetti-drift', drift + 'px');
                    piece.style.setProperty('--confetti-rotate', rotate + 'deg');
                    piece.style.width = size + 'px';
                    piece.style.height = size + 'px';
                    if (Math.random() > 0.6) piece.style.borderRadius = '50%';
                    confettiLayer.appendChild(piece);
                }
            }

            createBurst();
            setTimeout(createBurst, 300);
            setTimeout(createBurst, 600);
            setTimeout(function () { confettiLayer.innerHTML = ''; }, 3500);
        }

        document.querySelectorAll('.voucher-open-btn').forEach(function (button) {
            button.addEventListener('click', function () {
                const voucherName = button.getAttribute('data-voucher-name');
                if (dynamicVoucherTitle && voucherName) {
                    dynamicVoucherTitle.textContent = voucherName;
                }
            });
        });

        ['weeklyGamesVoucherModal', 'dynamicVoucherModal', 'badgeUnlockModal'].forEach(function (modalId) {
            const modalElement = document.getElementById(modalId);
            if (modalElement) {
                modalElement.addEventListener('shown.bs.modal', function () {
                    launchRewardConfetti(modalElement);
                    playRewardSound();
                });
            }
        });

        if (rewardsPage && badgeUnlockModalElement && window.bootstrap && window.localStorage) {
            const employeeId = rewardsPage.getAttribute('data-employee-id');
            const internFirstName = rewardsPage.getAttribute('data-intern-first-name') || 'Intern';
            const storageKey = employeeId ? 'famtech_reward_badges_seen_' + employeeId : null;
            const unlockedBadges = Array.from(document.querySelectorAll('.badge-card-base[data-badge-unlocked="true"]'));
            const currentBadgeKeys = unlockedBadges
                .map(function (badgeCard) { return badgeCard.getAttribute('data-badge-key'); })
                .filter(Boolean);

            let seenBadgeKeys = [];
            if (storageKey) {
                try {
                    seenBadgeKeys = JSON.parse(window.localStorage.getItem(storageKey) || '[]');
                } catch (error) {
                    seenBadgeKeys = [];
                }
            }

            const newlyUnlockedBadges = unlockedBadges.filter(function (badgeCard) {
                return !seenBadgeKeys.includes(badgeCard.getAttribute('data-badge-key'));
            });

            if (storageKey) {
                window.localStorage.setItem(storageKey, JSON.stringify(currentBadgeKeys));
            }

            if (newlyUnlockedBadges.length) {
                const badgeUnlockModal = bootstrap.Modal.getOrCreateInstance(badgeUnlockModalElement);
                let modalQueueIndex = 0;

                function showUnlockedBadge(index) {
                    const badgeCard = newlyUnlockedBadges[index];
                    if (!badgeCard) {
                        return;
                    }

                    const badgeName = badgeCard.getAttribute('data-badge-name') || 'New Badge Unlocked';
                    const badgeDescription = badgeCard.getAttribute('data-badge-description') || 'You earned a new badge on your rewards journey.';
                    const badgeIcon = badgeCard.getAttribute('data-badge-icon') || 'award-fill';

                    badgeUnlockModalTitle.textContent = 'You are a ' + badgeName + ', ' + internFirstName + '!';
                    badgeUnlockModalDescription.textContent = 'You have ' + badgeDescription.charAt(0).toLowerCase() + badgeDescription.slice(1) + ' Keep going to unlock more badges and rewards!';
                    badgeUnlockModalIcon.className = 'bi bi-' + badgeIcon;
                    badgeUnlockModal.show();
                }

                badgeUnlockModalElement.addEventListener('hidden.bs.modal', function () {
                    modalQueueIndex += 1;
                    if (modalQueueIndex < newlyUnlockedBadges.length) {
                        showUnlockedBadge(modalQueueIndex);
                    }
                });

                showUnlockedBadge(modalQueueIndex);
            }
        }
    });
// Animation
document.addEventListener("DOMContentLoaded", function () {
    AOS.init({
        duration: 400,
        once: true,
        easing: 'ease-out-quad'
    });
});
